@WorkflowMethod
public LoanOutcome process(LoanApp app) {
    kyc.verify(app.id());
    // Suspends without blocking threads
    boolean ok = Workflow.await(Duration.ofDays(5), 
                                () -> approved);
    if (ok) disbursal.run(app.id());
    return LoanOutcome.SUCCESS;
}

